-- 0003_claves_estables.sql — las claves de las tarjetas SEM dejan de depender del nombre de la campaña.
-- Formato nuevo: MARCA:SEM:plan:<unidad>:<pain point>  y  MARCA:SEM:anuncio:<campaña del informe>:<grupo>.
-- Se aplicó el 30 sep 2026. Conserva estado, orden, historial y quién movió cada tarjeta.
update seo_sem.recomendaciones r set clave = x.clave_nueva
