where r.tipo = 'SEM' and r.origen = x.origen and r.marca = x.marca and r.titulo = x.titulo
  and coalesce(r.evidencia->>'unidad', (select c.unidad from seo_sem.campanas c where c.id = r.campana_id)) = x.unidad;
